usages.expression:
useGetCompiledTrajectory(projectId, {
    query: { select: (response) => response.data as CompiledTrajectory },
  })

useListProjects({
    query: {
      select: (response) => {
        response.data.forEach((project) =>
          rememberProjectRevision(project.id, project.revision),
        );
        return response.data;
      },
    },
  })
